def protect_view(view_func):
    """
    Decorator for protecting the views checking user, redirecting
    to the log-in page if necessary or returning 404 status code
    """

    @wraps(view_func)
    def _wrapped_view(request, *args, **kwargs):
        if (
            not request.user.is_authenticated
            and helpdesk_settings.HELPDESK_REDIRECT_TO_LOGIN_BY_DEFAULT
        ):
            return redirect("helpdesk:login")
        elif (
            not request.user.is_authenticated
            and helpdesk_settings.HELPDESK_ANON_ACCESS_RAISES_404
        ):
            raise Http404
        if auth_redirect := helpdesk_settings.HELPDESK_PUBLIC_VIEW_PROTECTOR(request):
            return auth_redirect
        return view_func(request, *args, **kwargs)

    # This wrapper *is* helpdesk's anonymous-access policy: the three settings
    # above decide what an unauthenticated visitor gets. A host project running
    # Django 5.1's LoginRequiredMiddleware would redirect the request before it
    # ever reached here, silently turning all three settings into dead config
    # and hiding the public ticket forms. Opting out hands the decision back to
    # the policy that was written to make it.
    #
    # Applied after @wraps, which copies view_func.__dict__ onto the wrapper and
    # would otherwise clobber the attribute.
    return login_not_required(_wrapped_view)

