def get_under_login_required_middleware(self, url_name):
    """
    A fresh Client each time: the middleware chain is built on a handler's
    first request, so an already-used client would keep the old one.
    """
    with self.settings(
        MIDDLEWARE=[*settings.MIDDLEWARE, LOGIN_REQUIRED_MIDDLEWARE]
    ):
        return Client().get(reverse(url_name))

