BARE_RENDER_RE = re.compile(r"\{\{\s*([A-Za-z_][A-Za-z0-9_]*)\s*\}\}")

COMMENT_BLOCK_RE = re.compile(r"\{%\s*comment\s*%\}.*?\{%\s*endcomment\s*%\}", re.S)


def without_comment_blocks(source):
    """Blank out ``{% comment %}`` blocks, keeping the line numbering intact."""
    return COMMENT_BLOCK_RE.sub(
        lambda match: "\n" * match.group(0).count("\n"), source
    )
